// Author: MiYu. Browse local manual checkpoints with the source single-player load screen.
#include "saved_game_browser.h"
#include <algorithm>

namespace war3 {
namespace {
bool hit(GlueScreen::Rect r,float x,float y){return x>=r.x && y>=r.y && x<r.x+r.w && y<r.y+r.h;}
bool click(GlueScreen::Rect r,const UiInput& input){return input.pressed && hit(r,input.x,input.y) && hit(r,input.startX,input.startY);}
}
SavedGameBrowser::SavedGameBrowser(Archives& archives,Images& images,Renderer& renderer,Text& text,Log& log,const fs::path& dataRoot) : screen_(archives,images,renderer,text,"UI\\FrameDef\\Glue\\LoadSavedGameScreen.fdf","LoadSavedGameScreen"),renderer_(renderer),log_(log),resources_(archives.fork()) {
    try{validateWar3UserDirectory(dataRoot);auto base=war3UserDirectory()/L"Saves",directory=base/L"Manual";auto safe=[](const fs::path& path){auto a=GetFileAttributesW(path.c_str());return a==INVALID_FILE_ATTRIBUTES || ((a&FILE_ATTRIBUTE_DIRECTORY) && !(a&FILE_ATTRIBUTE_REPARSE_POINT));};if(!safe(base) || !safe(directory))throw std::runtime_error("Invalid save directory");if(fs::exists(directory))for(const auto& item:fs::directory_iterator(directory)){auto a=GetFileAttributesW(item.path().c_str());if(a==INVALID_FILE_ATTRIBUTES || (a&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)) || CompareStringOrdinal(item.path().extension().c_str(),-1,L".w3z",-1,TRUE)!=CSTR_EQUAL)continue;if(files_.size()>=10000)throw std::runtime_error("Too many saves");files_.push_back(item.path().stem().wstring());}std::sort(files_.begin(),files_.end(),[](const auto& a,const auto& b){return CompareStringOrdinal(a.c_str(),-1,b.c_str(),-1,TRUE)==CSTR_LESS_THAN;});}catch(const std::exception& e){files_.clear();error_="无法读取存档列表。";log_.write(std::string("saved_game_list_error=")+e.what());}worker_=std::jthread([this](std::stop_token stop){run(stop);});if(!files_.empty())select(0,1);screen_.focus(files_.empty()?"CancelButton":"OKButton");
}
SavedGameBrowser::~SavedGameBrowser() {{std::lock_guard lock(mutex_);worker_.request_stop();++generation_;pending_.reset();}wake_.notify_one();}
void SavedGameBrowser::run(std::stop_token stop){
    while(!stop.stop_requested()){std::pair<std::uint64_t,std::string> request;{std::unique_lock lock(mutex_);wake_.wait(lock,[&]{return stop.stop_requested() || pending_.has_value();});if(stop.stop_requested())return;request=std::move(*pending_);pending_.reset();}Result result;result.request=request.first;try{SavedGameSelection value;value.name=request.second;value.checkpoint=ScriptSession::inspectRecoveryCheckpoint(resources_->root(),value.name);value.map=ScriptSession::resolveRecoveryCheckpointMap(resources_->root(),value.name);resources_->mountMap(value.map);auto w3i=resources_->readCandidates({"war3map.w3i"},ArchiveScope::Map);if(!w3i)throw std::runtime_error("Saved map information is missing");MapStrings strings;if(auto wts=resources_->readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);value.info=MapInfo::parse(w3i->bytes,strings);resources_->unmountMap();result.value=std::move(value);}catch(const std::exception& e){resources_->unmountMap();result.error=e.what();}std::lock_guard lock(mutex_);if(!stop.stop_requested() && request.first==generation_)ready_=std::move(result);}
}
void SavedGameBrowser::prepared(){std::optional<Result> result;{std::lock_guard lock(mutex_);result=std::move(ready_);ready_.reset();}if(!result || result->request!=generation_)return;loading_=false;preview_=std::move(result->value);if(!preview_){openWhenReady_=false;previewError_="无法读取所选存档或定位地图。";log_.write("saved_game_preview_error="+result->error);}}
void SavedGameBrowser::select(size_t index,size_t rows){if(index>=files_.size())return;bool changed=!requested_ || index!=selected_;selected_=index;if(selected_<scroll_)scroll_=selected_;if(selected_>=scroll_+rows)scroll_=selected_-rows+1;if(!changed)return;requested_=true;preview_.reset();previewError_.clear();openWhenReady_=false;loading_=true;std::lock_guard lock(mutex_);auto id=++generation_;ready_.reset();pending_=std::pair{id,"Manual\\"+utf8(files_[selected_])+".w3z"};wake_.notify_one();}
std::optional<SavedGameSelection> SavedGameBrowser::selected() const {return preview_;}
std::string SavedGameBrowser::draw(const UiInput& input){
    prepared();auto list=screen_.bounds("FileListFrame");constexpr float step=.01875f;size_t rows=std::max(size_t(1),size_t(std::max(0.f,list.h-.008f)/step)),maximum=files_.size()>rows?files_.size()-rows:0;if(hit(list,input.x,input.y) && input.wheel)scroll_=size_t(std::clamp(std::int64_t(scroll_)-std::int64_t(input.wheel)*3,std::int64_t(0),std::int64_t(maximum)));if(!files_.empty()){if(input.key==VK_UP)select(selected_?selected_-1:0,rows);if(input.key==VK_DOWN)select(std::min(selected_+1,files_.size()-1),rows);if(input.key==VK_HOME)select(0,rows);if(input.key==VK_END)select(files_.size()-1,rows);if(input.key==VK_PRIOR)select(selected_>=rows?selected_-rows:0,rows);if(input.key==VK_NEXT)select(std::min(selected_+rows,files_.size()-1),rows);}
    auto track=GlueScreen::Rect{list.x+list.w-.0205f,list.y+.004f,.0165f,list.h-.008f},up=GlueScreen::Rect{track.x,track.y,track.w,.015f},down=GlueScreen::Rect{track.x,track.y+track.h-.015f,track.w,.015f},trough=GlueScreen::Rect{track.x,track.y+.015f,track.w,track.h-.03f};if(click(up,input) && scroll_)--scroll_;if(click(down,input) && scroll_<maximum)++scroll_;float travel=track.h-.04f;if(maximum && travel>0 && input.down && hit(trough,input.startX,input.startY))scroll_=size_t(std::clamp((input.y-trough.y-.005f)/travel,0.f,1.f)*float(maximum)+.5f);bool open=false;for(size_t row=0;row<rows && scroll_+row<files_.size();++row){GlueScreen::Rect area{list.x+.004f,list.y+.004f+float(row)*step,list.w-.0245f,step};if(click(area,input)){select(scroll_+row,rows);open=input.doubleClick;if(open && loading_){openWhenReady_=true;open=false;}break;}}std::set<std::string> enabled{"CancelButton"};if(preview_ && !loading_)enabled.insert("OKButton");auto action=screen_.draw("LoadSavedGameScreen",input,enabled,true);screen_.backdropAt("StandardEditBoxBackdropTemplate",list);float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f),left=(renderer_.width()-.8f*scale)/2,top=(renderer_.height()-.6f*scale)/2;for(size_t row=0;row<rows && scroll_+row<files_.size();++row){auto index=scroll_+row;GlueScreen::Rect area{list.x+.004f,list.y+.004f+float(row)*step,list.w-.0245f,step};if(index==selected_)renderer_.rect(left+area.x*scale,top+area.y*scale,area.w*scale,area.h*scale,0x9f344b6b);screen_.imageAt("UI\\Widgets\\Glues\\icon-file.blp",{area.x,area.y,.01875f,.01875f});screen_.textAt("StandardInfoTextTemplate",utf8(files_[index]),{area.x+.022f,area.y,area.w-.022f,area.h},true,index==selected_,true,.013f);}screen_.backdropAt("StandardScrollBarBackdrop",track);screen_.backdropAt("StandardScrollBarIncButtonBackdrop",up);screen_.backdropAt("StandardScrollBarDecButtonBackdrop",down);screen_.backdropAt("StandardThumbButtonBackdrop",{track.x+.00325f,track.y+.015f+(maximum?float(scroll_)/float(maximum)*travel:0),.01f,.01f});auto pane=screen_.bounds("MapInfoPaneContainer");if(preview_){auto& info=preview_->info;screen_.textAt("StandardInfoTextTemplate",info.name,{pane.x,pane.y,pane.w,.03f},true,false,true,.013f);screen_.textAt("StandardValueTextTemplate",info.author,{pane.x,pane.y+.035f,pane.w,.024f},true,false,true,.011f);screen_.textAt("StandardValueTextTemplate",info.description,{pane.x,pane.y+.065f,pane.w,.12f},true,false,true,.011f);}else if(loading_)screen_.textAt("StandardValueTextTemplate","正在读取存档…",{pane.x,pane.y,pane.w,.04f},true,false,true,.011f);auto message=previewError_.empty()?error_:previewError_;if(!message.empty())screen_.textAt("StandardValueTextTemplate",message,{pane.x,pane.y+.04f,pane.w,.05f},true,false,true,.011f);screen_.overlay();if(action=="CancelButton" || input.key==VK_ESCAPE){openWhenReady_=false;return "CancelButton";}if(preview_ && !loading_ && (action=="OKButton" || open || openWhenReady_)){openWhenReady_=false;return "LoadSavedGame";}return {};
}
}
